def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = []
    me = []
    oppD = 0
    meD = 0
    for h in history:
        m = h[0]
        o = h[1]
        me.append(m)
        opp.append(o)
        if m == 'D':
            meD += 1
        if o == 'D':
            oppD += 1
    oppC = n - oppD

    if oppD == 0:
        if n < 20:
            return 'C'
        dC = 0
        for i in range(max(0, n - 20), n - 1):
            if me[i] == 'D' and opp[i + 1] == 'C':
                dC += 1
        if dC >= 1:
            return 'D'
        if meD == 0:
            return 'D'
        if me[-1] == 'D':
            return 'C'
        return 'C'

    if oppD == n:
        return 'D'

    r6 = sum(1 for x in opp[-6:] if x == 'D')
    r10 = sum(1 for x in opp[-10:] if x == 'D')
    last_m = me[-1]
    last_o = opp[-1]

    after_C_C = after_C_D = after_D_C = after_D_D = 0
    start = max(0, n - 25)
    for i in range(start, n - 1):
        if me[i] == 'C':
            if opp[i + 1] == 'C':
                after_C_C += 1
            else:
                after_C_D += 1
        else:
            if opp[i + 1] == 'C':
                after_D_C += 1
            else:
                after_D_D += 1

    c_total = after_C_C + after_C_D
    if c_total >= 3:
        resp_to_C = after_C_C / c_total
    else:
        resp_to_C = oppC / n

    d_total = after_D_C + after_D_D
    if d_total >= 3:
        resp_to_D = after_D_C / d_total
    else:
        if oppD * 5 < n:
            resp_to_D = 0.55
        else:
            resp_to_D = 0.35

    if n >= 15:
        if (r10 >= 8 and oppD * 3 >= n) or (oppD * 5 >= n * 4) or (oppC <= 2 and n >= 8):
            return 'D'
        if oppD * 5 >= n * 2 and resp_to_C < 0.65:
            return 'D'

    if last_o == 'C':
        if last_m == 'D':
            if r6 <= 1 and oppD * 5 <= n and after_D_C >= 2 and after_D_D <= 1:
                return 'D'
            if n >= 90 and r10 == 0 and oppD * 10 <= n:
                return 'D'
            return 'C'

        if r10 >= 6 and resp_to_C < 0.7:
            return 'D'
        if meD <= 2 and oppD >= 4 and r10 >= 4 and oppD * 3 >= n:
            return 'D'
        if after_D_C >= 2 and after_D_D <= 1 and resp_to_D >= 0.75 and r10 <= 2 and oppD * 5 <= n:
            return 'D'
        if resp_to_C >= 0.72 or oppD * 3 < n:
            return 'C'
        if oppD * 2 < n and r6 <= 2:
            return 'C'
        return 'C'

    if last_m == 'D':
        if resp_to_C >= 0.72 and r6 <= 4:
            return 'C'
        if r6 >= 4:
            return 'D'
        if oppD * 2 >= n and resp_to_C < 0.65:
            return 'D'
        if oppD * 3 < n or r6 <= 2 or oppD <= 2:
            return 'C'
        return 'C'

    if meD <= 2 and oppD >= 3 and (r6 >= 2 or oppD * 3 >= n):
        return 'D'
    if r6 >= 3 or (n >= 2 and opp[-2] == 'D'):
        return 'D'
    if oppD == 1:
        return 'C'
    if oppD <= 2 and n >= 20 and oppD * 10 < n:
        return 'C'
    if resp_to_C >= 0.68 and oppD * 2 < n:
        return 'C'
    if oppD * 3 < n and r6 <= 2:
        return 'C'
    if oppD * 2 < n and r6 <= 3:
        return 'C'
    return 'D'
